theory.example:
void Exchange(int& left, int& right) {
  int saved = left;
  left = right;
  right = saved;
}
// saved хранит отдельное значение. left и right не перепривязываются: меняются их объекты.

references.example:
int main() {
  int length = 10;
  int& left = length;
  int& right = left;
  right = 13;
}
// left и right по-прежнему обозначают length, а не отдельные копии.

void ClampToZero(int& amount) {
  if (amount < 0) {
    amount = 0;
  }
}

int main() {
  int debt = -4;
  ClampToZero(debt);
}
// amount обозначает debt; вызов меняет int вызывающего кода.
